def chart(model, themed=False):
    metrics=model['metadata']['training_metadata']
    train,val=metrics['train_loss_history'],metrics['val_loss_history']
    start=5
    values=train[start:]+val[start:]
    low,maxv=min(values)-.12,max(values)+.12
    left,top,w,h=46,20,570,190
    def x(i):return left+(i-start)/(max(len(train),len(val))-1-start)*w
    def y(v):return top+h-(v-low)/(maxv-low)*h
    muted='var(--muted-foreground,#7a8599)' if themed else '#77849a'
    border='var(--border,#e1e6ef)' if themed else '#e1e6ef'
    a='var(--chart-1,#5b78b7)' if themed else '#5b78b7'
    b='var(--chart-2,#b27c9f)' if themed else '#b27c9f'
    chunks=[f'<svg viewBox="0 0 640 250" role="img" aria-label="Historical chat model training and validation loss after the initial learning phase. Training loss decreases while validation does not improve consistently.">']
    for i in range(5):
        v=low+(maxv-low)*i/4
        chunks.append(f'<path d="M{left},{y(v):.2f}h{w}" stroke="{border}"/><text x="5" y="{y(v)+4:.2f}" fill="{muted}" font-size="11">{v:.1f}</text>')
    for arr,color,label in [(train,a,'Training'),(val,b,'Validation')]:
        points=' '.join(f'{x(i):.2f},{y(v):.2f}' for i,v in enumerate(arr) if i>=start)
        chunks.append(f'<polyline points="{points}" fill="none" stroke="{color}" stroke-width="2"><title>{label} loss</title></polyline>')
    best=val.index(min(val));bestx=x(best)
    chunks.append(f'<path d="M{bestx:.2f},{top}v{h}" stroke="{b}" stroke-dasharray="4 4" opacity=".6"/><circle cx="{bestx:.2f}" cy="{y(val[best]):.2f}" r="4" fill="{b}"/>')
    chunks.append(f'<text x="{left}" y="238" fill="{muted}" font-size="11">Evaluation {start+1}</text><text x="475" y="238" fill="{muted}" font-size="11">Evaluation {len(val)}</text></svg>')
    return ''.join(chunks)

rows=''
for m in models:
    meta=m['metadata'];tm=meta['training_metadata'];pf=meta['preflight']
    rows+=f'<tr><th>{html.escape(m["name"])}</th><td>{meta["params"]/1e6:.1f}M</td><td>{pf["total_tokens"]:,}</td><td>{tm["best_val_loss"]:.3f}</td><td>{tm["best_val_loss_step"]:,}</td><td>{tm["total_training_time_sec"]/60:.1f} min</td></tr>'
